SET LOCAL statement_timeout='90s';
CREATE TEMP TABLE form_checks(name text PRIMARY KEY,passed boolean);
CREATE FUNCTION pg_temp.check(v boolean,n text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',n;END IF;INSERT INTO form_checks VALUES(n,true);END$$;
CREATE FUNCTION pg_temp.act(a text,p jsonb,k uuid DEFAULT gen_random_uuid()) RETURNS jsonb LANGUAGE sql AS $$SELECT public.erp_branch_execute(current_setting('cf.c')::uuid,'erp_contracting_forms_write',jsonb_build_object('p_cafe',current_setting('cf.c'),'p_action',a,'p_input',p,'p_request',k),public.erp_branch_context(current_setting('cf.c')::uuid)->'scope')$$;
CREATE FUNCTION pg_temp.deny(a text,p jsonb,n text,k uuid DEFAULT gen_random_uuid()) RETURNS void LANGUAGE plpgsql AS $$DECLARE blocked boolean:=false;BEGIN BEGIN PERFORM pg_temp.act(a,p,k);EXCEPTION WHEN OTHERS THEN IF SQLSTATE IN('42501','22023','40001','23503','23505','P0001','22P02') THEN blocked:=true;ELSE RAISE;END IF;END;PERFORM pg_temp.check(blocked,n);END$$;
DO $$DECLARE c uuid:='e6000000-0000-4000-8000-000000000001';owner_id uuid;staff_id uuid;plan text;project uuid:=gen_random_uuid();customer uuid:=gen_random_uuid();model uuid:=gen_random_uuid();related uuid:=gen_random_uuid();entry uuid:=gen_random_uuid();second uuid:=gen_random_uuid();req uuid:=gen_random_uuid();branch_a uuid:=gen_random_uuid();branch_b uuid:=gen_random_uuid();cfg jsonb;p jsonb;common jsonb;r jsonb;fields jsonb;vals jsonb;permissions jsonb;denied boolean;fileid uuid:=gen_random_uuid();before_hash text;allmodel uuid:=gen_random_uuid();allentry uuid:=gen_random_uuid();allfields jsonb:='[]';allvals jsonb:='{}';t text;f jsonb;v jsonb;imageid uuid:=gen_random_uuid();BEGIN
 SELECT id INTO owner_id FROM public.profiles WHERE role='cafe_owner' AND status='active' ORDER BY created_at LIMIT 1;
 SELECT id INTO staff_id FROM public.profiles WHERE id<>owner_id AND status='active' AND role<>'platform_admin' ORDER BY created_at LIMIT 1;
 SELECT id INTO plan FROM public.platform_plans WHERE active AND features?'finance' LIMIT 1;
 INSERT INTO public.cafes(id,owner_user_id,name,slug,status,is_public) VALUES(c,owner_id,'CONTRACT-FORMS-ROLLBACK-PROBE','contract-forms-rollback-probe','active',false);
 INSERT INTO public.subscriptions(cafe_id,plan_id,status,expires_at) VALUES(c,plan,'active',now()+interval '1 month');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);PERFORM set_config('cf.c',c::text,true);PERFORM brand_finance_private.seed(c);
 INSERT INTO public.bf_staff(cafe_id,user_id,name,role,active) VALUES(c,staff_id,'Forms manager','manager',true);
 INSERT INTO public.bf_parties(cafe_id,id,kind,name) VALUES(c,customer,'customer','Forms customer');
 common:=jsonb_build_object('id',project,'kind','project','title','Contract forms project','number','','revision',0,'customer_id',customer,'project_id',NULL,'source_id',NULL,'description','','start_date','','end_date','','date',current_date,'valid_until','','budget',100,'duration',1,'duration_unit','months','cost_center','Forms','tags','','assigned_users','[]'::jsonb,'active',true,'is_default',false,'followup_status','','custom_fields','{"legacy":"preserved"}'::jsonb,'retention_rate',0,'recovery_rate',0,'advance_amount',0,'lines','[]'::jsonb);
 PERFORM public.erp_branch_execute(c,'erp_contracting',jsonb_build_object('p_cafe_id',c,'p_action','save','p_input',common,'p_request_id',gen_random_uuid()),public.erp_branch_context(c)->'scope');
 SELECT md5(to_jsonb(d)::text) INTO before_hash FROM public.erp_contracting_documents d WHERE d.cafe_id=c AND d.id=project;
 permissions:='{"create":{"mode":"everyone","ids":[]},"read":{"mode":"everyone","ids":[]},"update":{"mode":"everyone","ids":[]},"delete":{"mode":"everyone","ids":[]},"fieldRules":[]}';
 fields:='[{"id":"title","label":"Title","type":"text","required":true,"options":[],"unique":true},{"id":"secret","label":"Secret","type":"text","required":false,"options":[]},{"id":"amount","label":"Amount","type":"number","required":false,"options":[],"minimum":0,"maximum":100},{"id":"choice","label":"Choice","type":"select","required":false,"options":["a","b"]},{"id":"rows","label":"Rows","type":"subform","required":false,"options":[],"fields":[{"id":"email","label":"Email","type":"email","required":true,"options":[]}]},{"id":"customer","label":"Customer","type":"dynamic","entity":"customers","required":false,"options":[]},{"id":"file","label":"File","type":"file","required":false,"options":[]},{"id":"rich","label":"Rich","type":"formatted","required":false,"options":[]}]';
 cfg:=jsonb_build_object('id',model,'revision',0,'kind','primary','key','project_information','name','Project information','active',true,'description','','nameField','title','fields',fields,'permissions',permissions);
 r:=pg_temp.act('model',cfg,req);PERFORM pg_temp.check(pg_temp.act('model',cfg,req)=r,'model retry identity');
 PERFORM pg_temp.deny('model',cfg||'{"name":"changed"}', 'changed retry denied',req);
 PERFORM pg_temp.deny('model',cfg-'revision','missing revision');
 PERFORM pg_temp.deny('model',cfg||'{"revision":4}','stale revision');
 PERFORM pg_temp.deny('model',cfg||jsonb_build_object('id',gen_random_uuid(),'key','second_primary'),'single primary model');
 PERFORM pg_temp.act('model',cfg||jsonb_build_object('id',related,'kind','related','key','inspections','name','Inspections'));
 vals:=jsonb_build_object('title','First','secret','private value','amount',12,'choice','a','rows',jsonb_build_array(jsonb_build_object('email','one@example.com')),'customer',customer,'rich','<b>Formatting</b>');
 p:=jsonb_build_object('id',entry,'revision',0,'projectId',project,'modelId',model,'draft',false,'values',vals);
 req:=gen_random_uuid();r:=pg_temp.act('entry',p,req);PERFORM pg_temp.check(pg_temp.act('entry',p,req)=r,'entry retry identity');
 PERFORM pg_temp.check((SELECT count(*)=1 FROM public.erp_contracting_form_entries WHERE cafe_id=c),'one actual entry');
 PERFORM pg_temp.check((public.erp_contracting_forms_read(c)#>>'{entries,0,values,secret}')='private value','owner actual reader');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('id',second),'single primary entry');
 PERFORM pg_temp.act('entry',p||jsonb_build_object('id',second,'modelId',related,'values',vals));PERFORM pg_temp.check(true,'same unique value allowed in different model');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('id',gen_random_uuid(),'modelId',related),'duplicate unique value in same model denied');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'values',vals||'{"amount":-1}'),'numeric minimum');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'values',vals||'{"choice":"wrong"}'),'invalid select');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'values',vals||'{"rows":[{"email":"wrong"}]}'),'nested email validation');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'values',vals||'{"rows":[{"email":"one@example.com","intruder":true}]}'),'nested unknown field rejected');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'values',vals||jsonb_build_object('customer',gen_random_uuid())),'foreign dynamic reference');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'values',vals||jsonb_build_object('file',gen_random_uuid())),'unowned file reference');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'projectId',gen_random_uuid()),'foreign project');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',1,'modelId',related),'cannot move record');
 PERFORM pg_temp.deny('delete',jsonb_build_object('id',model,'revision',1,'entity','model'),'model with values protected');
 denied:=false;BEGIN DELETE FROM public.erp_contracting_documents WHERE cafe_id=c AND id=project;EXCEPTION WHEN foreign_key_violation THEN denied:=true;END;PERFORM pg_temp.check(denied,'project references retained');
 INSERT INTO public.erp_files(id,cafe_id,entity_type,record_id,name,mime,size_bytes,sha256,path,uploaded,created_by) VALUES(fileid,c,'contracting_form_entry',entry,'form.pdf','application/pdf',10,repeat('a',64),c::text||'/contracting_form_entry/'||entry::text||'/'||fileid::text||'.pdf',true,owner_id);
 PERFORM erp_file_private.assert_record(c,'contracting_form_entry',entry,true);PERFORM pg_temp.check(true,'owner file dispatcher accepts entry');
 PERFORM pg_temp.act('entry',p||jsonb_build_object('revision',1,'values',vals||jsonb_build_object('file',fileid)));
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('id',second,'revision',1,'modelId',related,'values',vals||jsonb_build_object('file',fileid)),'file belongs to exact entry');
 PERFORM pg_temp.deny('delete',jsonb_build_object('id',entry,'revision',2,'entity','entry'),'file orphan deletion protected');
 FOREACH t IN ARRAY ARRAY['text','textarea','url','email','phone','date','time','currency','number','checkbox','location','file','image','subform','separator','select','multiselect','dynamic','multidynamic','static','formatted'] LOOP
  f:=jsonb_build_object('id','v_'||t,'label',t,'type',t,'required',false,'options',CASE WHEN t IN('select','multiselect') THEN '["a","b"]'::jsonb ELSE '[]'::jsonb END);
  IF t IN('dynamic','multidynamic') THEN f:=f||'{"entity":"customers"}';END IF;
  IF t='subform' THEN f:=f||'{"fields":[{"id":"email","label":"Email","type":"email","required":true,"options":[]}]}';END IF;
  allfields:=allfields||jsonb_build_array(f);
  v:=CASE WHEN t IN('static','separator','file','image') THEN NULL WHEN t IN('text','textarea','phone','formatted') THEN '"text"'::jsonb WHEN t='url' THEN '"https://example.com"'::jsonb WHEN t='email' THEN '"valid@example.com"'::jsonb WHEN t='date' THEN to_jsonb(current_date::text) WHEN t='time' THEN '"08:30"'::jsonb WHEN t IN('currency','number') THEN '2'::jsonb WHEN t='checkbox' THEN 'true'::jsonb WHEN t='location' THEN '{"latitude":24,"longitude":46}'::jsonb WHEN t='subform' THEN '[{"email":"nested@example.com"}]'::jsonb WHEN t='select' THEN '"a"'::jsonb WHEN t='multiselect' THEN '["a","b"]'::jsonb WHEN t='dynamic' THEN to_jsonb(customer::text) WHEN t='multidynamic' THEN jsonb_build_array(customer) END;
  IF v IS NOT NULL THEN allvals:=allvals||jsonb_build_object('v_'||t,v);END IF;
 END LOOP;
 PERFORM pg_temp.act('model',cfg||jsonb_build_object('id',allmodel,'kind','related','key','all_types','nameField','','fields',allfields));
 PERFORM pg_temp.act('entry',jsonb_build_object('id',allentry,'revision',0,'projectId',project,'modelId',allmodel,'draft',true,'values',allvals));
 INSERT INTO public.erp_files(id,cafe_id,entity_type,record_id,name,mime,size_bytes,sha256,path,uploaded,created_by) VALUES(imageid,c,'contracting_form_entry',allentry,'image.png','image/png',12,repeat('b',64),c::text||'/contracting_form_entry/'||allentry::text||'/'||imageid::text||'.png',true,owner_id);
 PERFORM pg_temp.act('entry',jsonb_build_object('id',allentry,'revision',1,'projectId',project,'modelId',allmodel,'draft',false,'values',allvals||jsonb_build_object('v_file',imageid,'v_image',imageid)));
 PERFORM pg_temp.check((SELECT NOT draft AND (SELECT count(*) FROM jsonb_object_keys(field_values))=19 FROM public.erp_contracting_form_entries WHERE id=allentry),'all21 definitions and19 actual value types roundtrip');
 EXECUTE 'SET LOCAL ROLE authenticated';r:=public.erp_contracting_forms_read(c);EXECUTE 'RESET ROLE';PERFORM pg_temp.check(jsonb_array_length(r->'entries')=3,'authenticated role executes actual public reader');
 permissions:=jsonb_set(permissions,'{fieldRules}',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'selector',jsonb_build_object('mode','users','ids',jsonb_build_array(staff_id)),'create',jsonb_build_array('title','amount','choice','rows','customer','rich'),'read',jsonb_build_array('title','amount','choice','rows','customer','rich'),'update',jsonb_build_array('title','amount','choice','rows','customer','rich'))));
 PERFORM pg_temp.act('model',cfg||jsonb_build_object('revision',1,'permissions',permissions));
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 r:=public.erp_contracting_forms_read(c);
 PERFORM pg_temp.check(NOT (r#>'{entries,0,values}')?'secret' AND NOT (r#>'{entries,0,values}')?'file','staff private fields hidden in actual reader');
 PERFORM pg_temp.check(NOT (r#>'{models,0}')?'permissions','staff selector metadata not disclosed');
 PERFORM pg_temp.deny('model',cfg||'{"revision":2}','manager cannot configure model');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',2,'values','{"secret":"changed"}'::jsonb),'hidden field write denied');
 PERFORM pg_temp.act('entry',p||jsonb_build_object('revision',2,'values','{"amount":20}'::jsonb));
 PERFORM pg_temp.check((SELECT field_values->>'secret'='private value' FROM public.erp_contracting_form_entries WHERE cafe_id=c AND id=entry),'partial updates preserve hidden field');
 denied:=false;BEGIN PERFORM erp_file_private.assert_record(c,'contracting_form_entry',entry,false);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.check(denied,'field-hidden staff cannot bypass through files');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 permissions:=jsonb_set(permissions,'{read}','{"mode":"none","ids":[]}');PERFORM pg_temp.act('model',cfg||jsonb_build_object('revision',2,'permissions',permissions));
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);r:=public.erp_contracting_forms_read(c);
 PERFORM pg_temp.check(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'models') x WHERE x->>'id'=model::text),'model selector hides metadata');
 PERFORM pg_temp.deny('delete',jsonb_build_object('id',entry,'revision',3,'entity','entry'),'hidden model cannot delete by old ID');
 UPDATE public.bf_staff SET role='auditor' WHERE cafe_id=c AND user_id=staff_id;
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',3,'values','{"amount":21}'::jsonb),'auditor no write');
 UPDATE public.bf_staff SET active=false WHERE cafe_id=c AND user_id=staff_id;
 denied:=false;BEGIN PERFORM public.erp_contracting_forms_read(c);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.check(denied,'foreign inactive user reader denied');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 INSERT INTO public.branches(id,cafe_id,name,active) VALUES(branch_a,c,'Forms A',true),(branch_b,c,'Forms B',true);
 INSERT INTO public.erp_branch_records(cafe_id,table_name,record_id,branch_id) VALUES(c,'erp_contracting_documents',project,branch_a);
 INSERT INTO public.erp_branch_scopes(cafe_id,user_id,branch_id,revision) VALUES(c,owner_id,branch_b,1);
 r:=public.erp_contracting_forms_read(c);PERFORM pg_temp.check(jsonb_array_length(r->'entries')=0,'project branch hides values');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',3,'values','{"amount":22}'::jsonb),'wrong project branch write');
 PERFORM pg_temp.deny('entry',p,'cached request rechecks project branch',req);
 denied:=false;BEGIN PERFORM erp_file_private.assert_record(c,'contracting_form_entry',entry,false);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.check(denied,'wrong branch files denied');
 UPDATE public.erp_branch_scopes SET branch_id=branch_a,revision=2 WHERE cafe_id=c AND user_id=owner_id;
 INSERT INTO public.erp_branch_settings(cafe_id,payload) VALUES(c,'{"shareCustomers":false}') ON CONFLICT(cafe_id) DO UPDATE SET payload=erp_branch_settings.payload||excluded.payload;
 INSERT INTO public.erp_branch_resources(cafe_id,kind,record_id,branch_id) VALUES(c,'customer',customer,branch_b);
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',3,'values',vals),'branch resource gate actual customer');
 DELETE FROM public.erp_branch_resources WHERE cafe_id=c AND kind='customer' AND record_id=customer;
 INSERT INTO public.bf_parties(cafe_id,id,kind,name) VALUES(c,'e6000000-0000-4000-8000-000000000009','customer','Hidden branch default');
 DELETE FROM public.erp_branch_resources WHERE cafe_id=c AND kind='customer' AND record_id='e6000000-0000-4000-8000-000000000009';
 INSERT INTO public.erp_branch_resources(cafe_id,kind,record_id,branch_id) VALUES(c,'customer','e6000000-0000-4000-8000-000000000009',branch_b);
 SELECT jsonb_agg(CASE WHEN ff->>'id'='customer' THEN ff||'{"defaultValue":"e6000000-0000-4000-8000-000000000009"}' ELSE ff END) INTO f FROM jsonb_array_elements(fields) ff;
 PERFORM pg_temp.act('model',cfg||jsonb_build_object('id',related,'kind','related','key','inspections','revision',1,'fields',f));
 UPDATE public.bf_staff SET active=true,role='manager' WHERE cafe_id=c AND user_id=staff_id;
 INSERT INTO public.erp_branch_scopes(cafe_id,user_id,branch_id,revision) VALUES(c,staff_id,branch_a,1);
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);r:=public.erp_contracting_forms_read(c);
 PERFORM pg_temp.check(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'models') mm CROSS JOIN LATERAL jsonb_array_elements(mm->'fields') ff WHERE mm->>'id'=related::text AND ff->>'id'='customer' AND ff?'defaultValue'),'hidden branch default not disclosed in model metadata');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 PERFORM pg_temp.check((SELECT md5(to_jsonb(d)::text)=before_hash FROM public.erp_contracting_documents d WHERE d.cafe_id=c AND d.id=project),'original project legacy fields immutable');
 PERFORM pg_temp.check(NOT EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=c) AND NOT EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=c),'forms have no financial or inventory side effects');
 PERFORM pg_temp.check((SELECT count(*)>=6 FROM public.erp_contracting_form_events WHERE cafe_id=c),'actual audit trail');
 PERFORM pg_temp.check(NOT has_table_privilege('authenticated','public.erp_contracting_form_entries','SELECT'),'no direct table grants');
 PERFORM pg_temp.check(NOT has_function_privilege('anon','public.erp_contracting_forms_read(uuid)','EXECUTE'),'anonymous rpc denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch FROM now())::bigint)))::text,true);
 PERFORM public.cancel_brand_account(c,'contract-forms-rollback-probe','isolated forms test',gen_random_uuid());
 denied:=false;BEGIN PERFORM public.erp_contracting_forms_read(c);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.check(denied,'archived reader denied');
 PERFORM pg_temp.deny('entry',p||jsonb_build_object('revision',3,'values','{"amount":23}'::jsonb),'archived writer denied');
 denied:=false;BEGIN DELETE FROM public.erp_contracting_form_entries WHERE cafe_id=c AND id=second;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.check(denied,'archived entry retention');
END $$;
SELECT jsonb_build_object('passed',true,'checks',(SELECT count(*) FROM form_checks),'assertions',(SELECT jsonb_agg(name ORDER BY name) FROM form_checks),'at',now()) AS result;
ROLLBACK;
